  // (AppData.sharedCached), invece di aspettare Firebase con lo splash davanti; Firebase li aggiorna appena risponde.
  const [bootCache] = useState(() => { try { return AppData.sharedCached(nowMs()); } catch (e) { return { values: {}, kinds: [], complete: false }; } });
  const [shared0] = useState(() => { const v = { ...AppData.sharedDefaults(nowMs()), ...bootCache.values }; addStandingsGuests(v.standings.guests); return v; });
  const [redOrb, setRedOrb] = useState(false);   // 15/11: pallino rosso (tre tocchi sulla stessa scheda)
  const [tvMode, setTvMode] = useState(() => local.get("bt-tv") === true);   // 15/11: modalità TV (schermo sempre acceso)
  useKeepAwake(tvMode);
  const [flash, setFlash] = useState(null);   // 15/11: pezzo indicato per un attimo (dal registro delle novità)
  const [duoOn, setDuoOn] = useState(false), [novitaSeen, setNovitaSeen] = useState(() => local.get(NOVITA_KEY));   // 15/11: Novità con Dot ed Enzo
  const [termCodes, setTermCodes] = useState(() => shared0.termCodes || []);   // 15/11: codici del terminale aggiunti dall'admin
  const [offline, setOffline] = useState(false);   // all'avvio qualcosa non si è potuto leggere: riga "Sei offline"
  // 14/11: modalità senza rete. Si apre da sola quando il telefono dice che non c'è rete, oppure a mano dalla riga
  // "Sei offline" (rete che c'è ma non risponde); "Riprova a collegarti" rilegge Firebase.
  const netOn = useNetOnline();
  const [offPick, setOffPick] = useState(false);
  const [offTry, setOffTry] = useState("idle");   // idle | trying | failed
  useEffect(() => { if (netOn && !offPick) setOffTry("idle"); }, [netOn]);
  const [pitBest, setPitBest] = useState(USER_INIT.pitBest);   // Garage: miglior tempo del Pit Stop Challenge
  const [highlights, setHighlights] = useState(shared0.highlights);   // archivio "Video HIGHLIGHTS esclusivi" (Premium)
  const [sillyPreds, setSillyPreds] = useState(USER_INIT.sillyPreds);       // Silly Season: { sedile: { pick, renew, at } }
  const [stratPreds, setStratPreds] = useState(USER_INIT.stratPreds);       // Tire Strategy Predictor: { gara: { stints, at } }
  const [sillyOfficial, setSillyOfficial] = useState(shared0.silly);       // comunicati ufficiali registrati dall'admin
  const [driverPhotos, setDriverPhotos] = useState(shared0.driverPhotos);  // foto dei piloti caricate dall'admin (Task 14)
  const [commonsPhotos, setCommonsPhotos] = useState(shared0.commonsPhotos);   // G30: foto di Commons scelte dall'admin
  const [trophyCfg, setTrophyCfg] = useState(shared0.trophies);   // 25/10: trofei cambiati da Firebase (shared/bt-trophies)
  commons.choice = commonsPhotos || commons.choice;
  useEffect(() => { commonsNotify(); }, [commonsPhotos]);
  const predictSeat = (id, pr) => { if (userDataWait()) return; setSillyPreds(x => x[id] ? x : { ...x, [id]: pr }); };
  const [articleId, setArticleId] = useState(null);
  const [chatId, setChatId] = useState(null);
  // Messaggi delle stanze (Firebase): { stanza: [{ id, from, text, at, aid, mine }] }. Ogni messaggio ha un id: serve a
  // segnalarlo ed eliminarlo (moderazione).
  const [chatMsgs, setChatMsgs] = useState({});
  const chats = CHAT_ROOMS.map(r => ({ ...r, messages: chatMsgs[r.id] || [] }));
  const [termsAccepted, setTermsAccepted] = useState(() => !!local.get(TERMS_KEY));   // al primo avvio no: Termini prima di tutto
  const [termsOpen, setTermsOpen] = useState(false);         // rilettura dal profilo
  const acceptTerms = () => { local.set(TERMS_KEY, { ts: Date.now() }); setTermsAccepted(true); setTermsOpen(false); };
  const [splash, setSplash] = useState(true);                // avvio: logo e "Caricamento…"
  const [sharedReady, setSharedReady] = useState(false);     // prima lettura dei contenuti di Firebase finita (anche senza rete)
  const [feedbackOpen, setFeedbackOpen] = useState(false);
  const [feedbackAsk, setFeedbackAsk] = useState(() => local.get(FEEDBACK_ASK_KEY));   // { at, read, done } o null
  const saveAsk = a => { local.set(FEEDBACK_ASK_KEY, a); setFeedbackAsk(a); };
  useEffect(() => { const ask = countVisit(); if (ask) setFeedbackAsk(ask); }, []);   // questa apertura è un accesso
  // Feedback inviato (dal Profilo o dalla notifica): la richiesta sparisce e non torna più.
  const sendFeedback = f => Feedback.send({ ...f, email: account ? account.email : "", name: account ? (account.nick || account.name || "") : "" }).then(r => {
    saveAsk({ ...(local.get(FEEDBACK_ASK_KEY) || { at: Date.now(), read: true }), done: true });
    return r;
  });
  const [reports, setReports] = useState([]);   // segnalazioni per il moderatore (shared/bt-chat-reports)
  const [banned, setBanned] = useState([]);     // utenti sospesi dalla chat (shared/bt-chat-banned)
  const [blocked, setBlocked] = useState(() => Chat.blocked());   // utenti che ho bloccato (solo su questo telefono)
  const [saved, setSaved] = useState(USER_INIT.saved);       // articoli salvati tra i preferiti (id)
  const [savedOnly, setSavedOnly] = useState(false); // Home: mostra solo i salvati
  // FantaF1 come F1 Fantasy: la squadra, quella dell'ultima chiusura (per contare i cambi) e i cambi gratis.
  const [squad, setSquad] = useState(USER_INIT.squad);
  const [squadBase, setSquadBase] = useState(USER_INIT.squadBase);
  const [freeTransfers, setFreeTransfers] = useState(USER_INIT.freeTransfers);
  const [fantaWeekends, setFantaWeekends] = useState([]);   // punti delle sessioni già corse: { id, raceId, type, total, lines }
  const [predictions, setPredictions] = useState(shared0.predictions);   // previsioni avanzate (+1 punto), dell'admin
  const [predAnswers, setPredAnswers] = useState(USER_INIT.predAnswers);   // { idDomanda: risposta }
  const [lastRace, setLastRace] = useState(LAST_RACE_INIT);           // ultima gara: podio e classifica
  // 31/10: FantaF1 vero. squadLog = storia della squadra (account); leagueCodes = codici delle mie leghe (account);
  // leagues = le leghe lette da Firebase; fantaRounds = risultati veri della stagione (Jolpica).
  const [squadLog, setSquadLog] = useState(USER_INIT.squadLog);
  const [leagueCodes, setLeagueCodes] = useState(USER_INIT.leagues);
  const [autoLeagues, setAutoLeagues] = useState(USER_INIT.autoLeagues);
  const [promoMine, setPromoMine] = useState(USER_INIT.promo);   // 21/11: codici promo (src/logic/promo.js)
  const [leagues, setLeagues] = useState([]);
  const [fantaRounds, setFantaRounds] = useState([]);
  const [homePoll, setHomePoll] = useState(shared0.homePoll);    // sondaggio della Home (Premium); null = nessuno
  // 31/10: temi delle feste: comando dell'admin (shared/bt-holidays) e scelta dell'utente (Profilo; sul telefono per l'avvio).
  const [flags, setFlags] = useState(() => shared0.flags || local.get("bt-flags-cfg") || { pitSwipe: false });   // 7/11: funzioni accese dall'admin
  const [holidayCfg, setHolidayCfg] = useState(() => shared0.holidays || local.get("bt-holidays-cfg") || { force: null, off: [] });
  const [holidaysOn, setHolidaysOn] = useState(() => local.get("bt-holidays-on") !== false);
  // Pit Swipe (1/11): dati dell'account (gusti, mazzo, serie, missioni, easter egg), opinioni dell'admin, voti veri.
  const [swipe, setSwipe] = useState(USER_INIT.swipe);
  const [takes, setTakes] = useState(shared0.takes || []);
  const [psVotes, setPsVotes] = useState([]);
  const [psRes, setPsRes] = useState(null);       // risultato dell'ultima opinione o vero o falso
  const [psRain, setPsRain] = useState(false);    // easter egg: pioggia vera sul circuito del weekend
  const [launchFx, setLaunchFx] = useState(0);    // easter egg: launch control (la pagina "parte")
  const [duelsArr, setDuelsArr] = useState([]);   // sfide 1 contro 1 (fanta/pitswipe-sfide)
  const [activeDuel, setActiveDuel] = useState(null);
  const [garageGame, setGarageGame] = useState(null);
  const [welcome, setWelcome] = useState(null);   // Bentornato
  // Mini Pit Board in tutta l'app (31/10 sera): interruttore nel Profilo (sul telefono) e sessione chiusa con la X.
  const [miniPitOn, setMiniPitOn] = useState(() => local.get("bt-minipit-on") !== false);
  const [miniPitHidden, setMiniPitHidden] = useState(null);
  const [votes, setVotes] = useState(USER_INIT.votes);           // { idSondaggio: idRisposta }
  const [notifsRaw, setNotifsRaw] = useState(shared0.notifs);    // shared/bt-notifs come sono salvate
  const [localNotifs, setLocalNotifs] = useState([]);            // avvisi di questo telefono (notizia sul tuo preferito)
  const [notifSeenAt, setNotifSeenAt] = useState(USER_INIT.notifSeenAt);   // ora dell'ultima "Segna tutte come lette"
  const [premiumOpen, setPremiumOpen] = useState(false);
  // Premium: si salva nell'account (users/<email>.app2.premium) e torna riaprendo l'app; la prova finisce da sola.
  const [premium, setPremium] = useState(USER_INIT.premium);
  const trial = premium.trial;   // prova gratuita: { start, end } (una sola volta)
  // 29/10: Pro con una pubblicità con premio, solo in memoria: finisce chiudendo l'app o spegnendo lo schermo (pagina
  // nascosta). Mentre l'annuncio è sullo schermo (e un attimo dopo) la pagina nascosta non conta.
  const [adPro, setAdPro] = useState(false), [adBusy, setAdBusy] = useState(false);
  const adShowing = useRef(0);
  useEffect(() => {
    const h = () => { if (document.hidden && performance.now() > adShowing.current) setAdPro(false); };
    document.addEventListener("visibilitychange", h);
    return () => document.removeEventListener("visibilitychange", h);
  }, []);
  const isAdminNow = !!account && Account.isAdmin();   // 31/10: gli admin hanno Premium e tutti i trofei, gratis
  // 1/11: isPaid = Premium vero (abbonamento, prova, admin): niente pubblicità e notizie Premium. isPremium = funzioni Pro,
  // anche col video con premio (adPro): un video le sblocca tutte, ma i banner restano e le notizie si sbloccano una per video.
  // Finché i dati dell'account non sono arrivati (premLoaded) vale il Premium letto col profilo, così chi è Premium non vede
  // per un attimo i lucchetti; poi vale premium (app2.premium, aggiornato anche quando un abbonamento di Google Play finisce).
  const [premLoaded, setPremLoaded] = useState(null);
  const accPaid = !!account && (account.paidPremium !== undefined ? account.paidPremium : !!account.isPremium);
  const accEcho = !!account && premLoaded !== account.email && !!account.isPremium;
  const [trophies, setTrophies] = useState(USER_INIT.trophies);   // trofei vinti (G31): { id: data in ms }
  // 8/11 (Edoardo: "solo chi ha ottenuto tutti i trofei può avere il premium"): vinti tutti i trofei che si possono vincere
  // adesso (senza Pit Swipe acceso non contano i suoi), l'app dà il Premium (src/logic/trophypro.js).
  const trophySkip = flags && flags.pitSwipe ? [] : BtTrophyPro.PIT_SWIPE_TROPHIES;
  // 14/11: sblocchi del terminale del box, solo su questo telefono (src/logic/secret-codes.js). Pit Swipe acceso da un
  // codice non cambia la regola del Premium coi trofei (trophySkip resta quello dell'admin).
  const [unlocks, setUnlocks] = useState(() => SecretCodes.clean(local.get("bt-unlocks")));
  const toggleUnlock = id => setUnlocks(l => { const next = SecretCodes.toggle(l, id); local.set("bt-unlocks", next); return next; });
  const trophyAll = BtTrophyPro.allDone(trophies, trophyDefs(trophyCfg), { skip: trophySkip });
  const isPaid = accPaid || accEcho || premium.sub || (!!trial && nowMs() < trial.end) || isAdminNow || trophyAll;
  // 14/11: TELEMETRIA nel terminale del box: solo cose vere di questo telefono e di questa sessione.
  const hackTelemetry = () => {
    const sizes = local.get("bt-sc-sizes"), kinds = sizes && typeof sizes === "object" ? Object.keys(sizes) : [];
    const kb = Math.round(kinds.reduce((n, k) => n + (Number(sizes[k]) || 0), 0) / 1024);
    const online = typeof navigator === "undefined" || navigator.onLine !== false;
    return [
      ["VERSIONE", APP_VERSION],
      ["RETE", !online ? "OFFLINE" : offline ? "LENTA (qualcosa non è arrivato)" : "ONLINE"],
      ["ACCOUNT", guest || !account ? "OSPITE" : account.loaded ? "ENTRATO" : "ENTRATO (profilo dell'ultima volta)"],
      ["PREMIUM", isPaid ? "SÌ" : "NO"],
      ["COPIA SUL TEL", kinds.length + " contenuti, " + kb + " KB"],
      ["ORA DI ROMA", fmtRome(nowMs())],
    ];
  };
  // 21/11: un codice promo dà le Funzioni Pro per qualche giorno (come il video, mai il Premium vero). Il tasto in alto
  // e la scheda Premium del Profilo usano isPaid: col video o col codice non dicono "Sei B&T Premium".
  const promoPro = BtPromo.proActive(promoMine, nowMs());
  const isPremium = isPaid || adPro || promoPro;
  // 14/11: archivio storico dei GP (Contenuti Premium): senza Premium si apre la finestra Premium.
  const openArchive = () => { if (!isPremium) { setPremiumOpen(true); return; } setView("archivio"); fx.play("tick"); };
  const [archiveRound, setArchiveRound] = useState(null);   // 22/11: gara del 2026 da aprire nell'archivio (notifica della gara)
  // 22/11: tocco su una notifica dei risultati. Qualifica: pagina Race, alla griglia di partenza. Sprint: pagina Race.
  // Gara: il Replay di quella gara (archivio, Premium; se i dati della gara non ci sono ancora, l'elenco delle gare).
  const openResult = a => {
    const [, kind, round] = String(a).split(":");
    const n = resNotifsRef.current.find(x => x.action === a);
    if (n) markResRead(n.id);
    fx.play("tick");
    if (kind === "race") {
      if (!isPremium) { setPremiumOpen(true); return; }
      setArchiveRound(Number(round) || null);
      setView("archivio");
      return;
    }
    goTab("race");
    if (kind === "quali") {
      let tries = 0;
      const look = () => { const g = document.querySelector("[data-start-grid]"); if (g && g.scrollIntoView) g.scrollIntoView({ behavior: prefersReduced() ? "auto" : "smooth", block: "start" }); else if (++tries < 12) setTimeout(look, 250); };
      setTimeout(look, 300);
    }
  };
  adsTestForAdmin = isAdminNow;
  adsMinor = !!account && under18(account.about, nowMs());   // 14/11: minori → annunci non personalizzati
  const [proAsk, setProAsk] = useState(null);   // foglio "Funzione Pro": { what, then }
  const [champSeen, setChampSeen] = useState(false);
  const [payFail, setPayFail] = useState(false);   // 4/11: carta che si gira se il pagamento non va   // 2/11: schermata del campione chiusa in questa apertura
  const proGate = (what, then) => { if (proHas(what)) then(); else setProAsk({ what, then }); };   // 7/11: anche coi trofei
  // Notizie Premium sbloccate col video: restano sbloccate su questo telefono (le ultime 200).
  const [adNews, setAdNews] = useState(() => { const v = local.get("bt-ad-news"); return Array.isArray(v) ? v : []; });
  const [plan, setPlan] = useState("annual");
  const [subscribing, setSubscribing] = useState(false);
  const [toast, setToast] = useState(null);
  const toastTimer = useRef(null);
  const [selectedDriver, setSelectedDriver] = useState(null);
  // Link dell'app in chat (25/10): "Invia in chat" sceglie la stanza (linkShare), poi il link si allega (pendingLink);
  // aperto un link dalla chat, Indietro torna in chat (linkFrom); il Ghost Lap si apre sulla curva del link (ghostInit).
  const [linkShare, setLinkShare] = useState(null), [pendingLink, setPendingLink] = useState(null);
  const [linkFrom, setLinkFrom] = useState(null), [ghostInit, setGhostInit] = useState(null);
  const [liveTrackOpen, setLiveTrackOpen] = useState(false);
  const [infoModal, setInfoModal] = useState(null);
  const [articles, setArticles] = useState(shared0.news);
  const [tagFilter, setTagFilter] = useState(null);
  const [favTeam, setFavTeam] = useState(USER_INIT.favTeam);
  const [favDriver, setFavDriver] = useState(USER_INIT.favDriver);
  const [notifPrefs, setNotifPrefs] = useState(USER_INIT.notifPrefs);
  // 8/11 (Edoardo: "metti la possibilità di togliere i B&T Trophies"): scelta di questo telefono.
  const [trophiesOff, setTrophiesOff] = useState(() => local.get("bt-trophies-off") === true);
