        if (cur !== el) return;
        el.scrollTop = want; el.scrollLeft = wantX;
        if ((Math.abs(el.scrollTop - want) > 2 || Math.abs(el.scrollLeft - wantX) > 2) && n++ < 60) raf = requestAnimationFrame(go);
